// Phase 2 / Module 11: Advanced Python Features.
"use strict";
const { chain, graph, table } = require("./render");
const { mcq, task } = require("./lib");

const lessons = [];

// ---------------------------------------------------------------- 1
lessons.push({
  title: "Iterables, Iterators and Generators in Depth",
  minutes: 50,
  learn: ["Explain the iteration protocol behind every for loop", "Write a class-based iterator", "Use generators, yield from and generator expressions", "Stream large data without loading it all"],
  why: "Everything you loop over in Python works through one protocol. Knowing it explains generators, files, dictionaries, range and zip, and lets you build your own sequences.",
  realWorld: "Reading a 20 GB log line by line, paging through API results, producing an endless stream of IDs.",
  simple: "An <strong>iterable</strong> can give you an <strong>iterator</strong> (<code>iter(x)</code>). An iterator hands out one item per <code>next()</code> call and raises <code>StopIteration</code> when it is finished. A <code>for</code> loop does exactly that behind the scenes.",
  detail: `<h3>The protocol</h3>
${table(["Object", "Must provide", "Examples"], [["Iterable", "<code>__iter__()</code> returning an iterator", "list, str, dict, set, range, file"], ["Iterator", "<code>__next__()</code> (and <code>__iter__()</code> returning itself)", "generator, <code>iter(list)</code>, zip, map, file object"]])}
<p><code>for x in obj</code> is: <code>it = iter(obj)</code>, then repeat <code>x = next(it)</code> until <code>StopIteration</code>. Iterators are <strong>one-shot</strong>: once exhausted they stay empty. Iterables such as lists can create a fresh iterator each time.</p>
<h3>Writing an iterator class</h3>
<pre style="background:rgba(127,127,127,.14);padding:12px 14px;border-radius:8px"><code>class Evens:\n    def __init__(self, limit):\n        self.n, self.limit = 0, limit\n    def __iter__(self):\n        return self\n    def __next__(self):\n        if self.n >= self.limit:\n            raise StopIteration\n        value = self.n\n        self.n += 2\n        return value</code></pre>
<h3>Generators are shorter</h3>
<p>The same thing as a generator function is three lines (<code>while n &lt; limit: yield n; n += 2</code>). <code>yield from other</code> delegates to another iterable. A generator expression <code>(x * x for x in data)</code> is lazy; a list comprehension is eager.</p>
<h3>Useful tools</h3>
<ul><li><code>next(it, default)</code> avoids <code>StopIteration</code> on an empty iterator.</li><li><code>iter(callable, sentinel)</code> calls a function until it returns the sentinel.</li><li>Many built-ins accept any iterable: <code>sum</code>, <code>max</code>, <code>sorted</code>, <code>list</code>, <code>set</code>, <code>"".join</code>.</li></ul>`,
  syntax: { code: `it = iter(items)\nnext(it)              # next item\nnext(it, None)        # default instead of StopIteration\ndef gen():\n    yield 1\n    yield from [2, 3]`, note: "StopIteration ends a for loop quietly." },
  diagram: graph("What a for loop does", "A for loop calls iter() once to get an iterator, then calls next() repeatedly until StopIteration is raised.", 640, 190,
    [{ id: "f", k: "term", t: "for x in data:", x: 100, y: 95, w: 150, h: 40 }, { id: "i", k: "proc", t: "it = iter(data)", x: 290, y: 40, w: 160, h: 40 }, { id: "n", k: "dec", t: "next(it)\nreturns item?", x: 290, y: 140, w: 160, h: 62 }, { id: "b", k: "proc", t: "run the loop body", x: 540, y: 140, w: 150, h: 40 }],
    [{ from: "f", to: "i" }, { from: "i", to: "n" }, { from: "n", to: "b", label: "item" }]),
  example: { code: `class Evens:\n    def __init__(self, limit):\n        self.n, self.limit = 0, limit\n    def __iter__(self):\n        return self\n    def __next__(self):\n        if self.n >= self.limit:\n            raise StopIteration\n        value = self.n\n        self.n += 2\n        return value\n\nprint(list(Evens(9)))\nit = iter([10, 20])\nprint(next(it), next(it), next(it, "done"))\n\ndef chunks(items, size):\n    for start in range(0, len(items), size):\n        yield items[start:start + size]\nprint(list(chunks([1, 2, 3, 4, 5], 2)))\n\ndef both():\n    yield from "ab"\n    yield from range(2)\nprint(list(both()))\n\nsquares = (n * n for n in range(5))\nprint(next(squares), sum(squares))\nreads = iter([3, 2, 1, 0, 9])\nprint(list(iter(lambda: next(reads), 0)))`, out: `[0, 2, 4, 6, 8]\n10 20 done\n[[1, 2], [3, 4], [5]]\n['a', 'b', 0, 1]\n0 30\n[3, 2, 1]` },
  lineByLine: [["__iter__ returns self, __next__ raises StopIteration", "Makes <code>Evens</code> an iterator usable in any loop."], ["next(it, \"done\")", "A default prevents StopIteration."], ["yield items[start:start + size]", "Produces the data one chunk at a time."], ["yield from \"ab\"", "Hands out each item of another iterable."], ["next(squares), sum(squares)", "The first item is taken (0); sum consumes the rest: 1+4+9+16 = 30."], ["iter(lambda: next(reads), 0)", "Keeps calling until the function returns the sentinel 0."]],
  dryRun: { intro: "<code>list(Evens(5))</code>:", headers: ["next() call", "self.n before", "returns", "self.n after"], rows: [["1", "0", "0", "2"], ["2", "2", "2", "4"], ["3", "4", "4", "6"], ["4", "6 (>= 5)", "StopIteration", "-"]] },
  realExample: { intro: "Process a big sequence lazily and stop early. No list of a million items is ever created.", code: `def numbers():\n    n = 1\n    while True:\n        yield n\n        n += 1\n\ndef first_square_over(limit):\n    for n in numbers():\n        if n * n > limit:\n            return n\n\nprint(first_square_over(1_000_000))`, out: `1001` },
  mistakes: ["Reusing an exhausted iterator.", "Forgetting <code>__iter__</code> on an iterator class.", "Calling <code>len()</code> on a generator.", "Building a list when a generator would do.", "Catching StopIteration inside a generator (it becomes RuntimeError since Python 3.7)."],
  practices: ["Use generators for pipelines over large data.", "Use <code>for</code> rather than manual <code>next()</code>.", "Turn into a list only when you need to reuse or index the data."],
  interview: ["What is the difference between an iterable and an iterator?", "How does a for loop work internally?", "Generator vs list comprehension?", "What does yield from do?"],
  practiceQs: ["Write a generator of Fibonacci numbers.", "What does iter(\"abc\") return?", "Why can you loop over a list twice but not a generator?", "Read a file lazily in chunks."],
  revision: ["iter() → iterator; next() until StopIteration.", "Iterators are one-shot.", "Generators: yield, yield from, expressions.", "next(it, default)."],
  hinglish: "for loop andar se iter() aur next() chalata hai jab tak StopIteration na aaye. Iterator ek baar khatam ho gaya to khali ho jata hai. Generator se bade data ko ek ek karke process karte hain, poori list banane ki zaroorat nahi.",
  quiz: [
    mcq("What does a for loop call first on the object?", ["next()", "iter()", "len()", "sorted()"], 1, "iter() creates the iterator."),
    mcq("What is raised when an iterator has no more items?", ["IndexError", "StopIteration", "EOFError", "ValueError"], 1, "StopIteration signals the end."),
    mcq("What is printed?\n\ng = (n for n in range(3))\nlist(g)\nprint(list(g))", ["[0, 1, 2]", "[]", "[3]", "Error"], 1, "The generator is exhausted.", "OUTPUT_PREDICTION"),
    mcq("What does next(iter([]), \"x\") return?", ["x", "None", "StopIteration", "[]"], 0, "The default is returned for an empty iterator.", "OUTPUT_PREDICTION"),
    mcq("Which is lazy?", ["[x for x in data]", "(x for x in data)", "list(data)", "sorted(data)"], 1, "Generator expressions produce items on demand.")
  ],
  tasks: [task("Even numbers iterator", "Write an iterator class Evens(limit) that yields the even numbers 0, 2, 4, ... below limit using __iter__ and __next__. Read limit and print the numbers on one line separated by spaces.", "class Evens:\n    pass\n\nlimit = int(input())\n# print the numbers produced by Evens(limit)\n", `class Evens:\n    def __init__(self, limit):\n        self.n, self.limit = 0, limit\n    def __iter__(self):\n        return self\n    def __next__(self):\n        if self.n >= self.limit:\n            raise StopIteration\n        value = self.n\n        self.n += 2\n        return value\n\nlimit = int(input())\nprint(" ".join(str(v) for v in Evens(limit)))`, [["10", "0 2 4 6 8"], ["3", "0 2"]], [["10", "0 2 4 6 8"], ["3", "0 2"], ["1", "0"], ["2", "0"], ["13", "0 2 4 6 8 10 12"]])],
});

