lessons.push({
  title: "Regular Expressions with the re Module",
  minutes: 55,
  learn: ["Read and write basic regular expression patterns", "Use search, match, fullmatch, findall, finditer, sub and split", "Capture groups and named groups", "Know the limits of regular expressions"],
  why: "Validating phone numbers and emails, extracting dates from text, cleaning data and searching logs are pattern problems. Regular expressions describe the pattern instead of coding it by hand.",
  realWorld: "Checking that a mobile number is valid, pulling all prices from a page of text, masking digits in a log.",
  simple: "A <strong>regular expression</strong> is a tiny language for describing text patterns: <code>\\d{3}-\\d{4}</code> means three digits, a dash, four digits. Always write them as raw strings: <code>r'...'</code>.",
  detail: `<h3>Pattern building blocks</h3>
${table(["Pattern", "Meaning"], [["<code>.</code>", "any character except newline"], ["<code>\\d  \\w  \\s</code>", "digit; letter, digit or underscore; whitespace (capitals negate: <code>\\D</code>)"], ["<code>[abc]  [a-z]  [^0-9]</code>", "one of; range; not one of"], ["<code>*  +  ?  {n}  {n,m}</code>", "0 or more; 1 or more; optional; exactly n; n to m times"], ["<code>^  $  \\b</code>", "start; end; word boundary"], ["<code>( )  (?P&lt;name&gt; )  |</code>", "group; named group; alternative"], ["<code>*?  +?</code>", "lazy (shortest) versions of the repeaters"]])}
<h3>Functions</h3>
${table(["Call", "Returns"], [["<code>re.search(p, s)</code>", "first match anywhere, or None"], ["<code>re.match(p, s)</code>", "match only at the start"], ["<code>re.fullmatch(p, s)</code>", "match of the whole string (best for validation)"], ["<code>re.findall(p, s)</code>", "list of all matches (or of groups)"], ["<code>re.finditer(p, s)</code>", "iterator of match objects"], ["<code>re.sub(p, repl, s)</code>", "replace matches"], ["<code>re.split(p, s)</code>", "split at matches"], ["<code>re.compile(p, flags)</code>", "reuse a compiled pattern; flags <code>re.I</code>, <code>re.M</code>, <code>re.X</code>"]])}
<p>A match object has <code>.group()</code>, <code>.group(1)</code>, <code>.groups()</code>, <code>.groupdict()</code>, <code>.start()</code>, <code>.end()</code>. Always test <code>if m:</code> before using it.</p>
<h3>Limits and safety</h3>
<ul><li>Regular expressions cannot parse nested structures such as HTML or JSON; use a real parser.</li><li>Email validation by regex is only a rough check; confirm by sending an email.</li><li>Patterns with nested repeaters such as <code>(a+)+</code> can take exponential time on crafted input (ReDoS). Keep patterns simple and anchored.</li></ul>`,
  syntax: { code: `import re\nm = re.search(r"(\\d+)-(\\d+)", text)\nif m:\n    a, b = m.groups()\nre.findall(r"\\b\\w+@\\w+\\.\\w+\\b", text)\nre.sub(r"\\s+", " ", text)\nre.fullmatch(r"[6-9]\\d{9}", phone)`, note: "Use raw strings for patterns." },
  diagram: chain("Reading a pattern", "Left to right: the pattern [6-9]\\d{9} is a first digit from 6 to 9 followed by exactly nine digits.",
    [{ k: "proc", t: "[6-9]\nfirst digit\n6 to 9" }, { k: "proc", t: "\\d{9}\nnine more\ndigits" }, { k: "term", t: "10-digit\nmobile number" }], { w: 150, gap: 40, hgt: 70 }),
  example: { code: `import re\ntext = "Call 98765-43210 or 9123456780; price Rs 250 and Rs 1,200."\nprint(re.findall(r"\\d+", "a1b22c333"))\nm = re.search(r"(\\d{5})-(\\d{5})", text)\nprint(m.group(), m.groups(), m.start())\nprint(re.fullmatch(r"[6-9]\\d{9}", "9123456780") is not None, re.fullmatch(r"[6-9]\\d{9}", "1234567890") is not None)\nprint(re.sub(r"\\d", "#", "OTP 4821"))\nprint(re.split(r"[,;]\\s*", "a, b;c,d"))\nprint(re.findall(r"Rs ([\\d,]+)", text))\nd = re.search(r"(?P<year>\\d{4})-(?P<month>\\d{2})", "Due 2026-11-30")\nprint(d["year"], d.groupdict())\nprint(re.findall(r"<.+?>", "<a><b>"), re.findall(r"<.+>", "<a><b>"))\nprint(re.findall(r"cat", "Cat cat CAT", re.I))`, out: `['1', '22', '333']\n98765-43210 ('98765', '43210') 5\nTrue False\nOTP ####\n['a', 'b', 'c', 'd']\n['250', '1,200']\n2026 {'year': '2026', 'month': '11'}\n['<a>', '<b>'] ['<a><b>']\n['Cat', 'cat', 'CAT']` },
  lineByLine: [["\\d+", "One or more digits: three separate numbers."], ["m.group(), m.groups(), m.start()", "Whole match, the groups and the starting position."], ["fullmatch(r\"[6-9]\\d{9}\", ...)", "The whole string must be a 10-digit number starting with 6-9."], ["re.sub(r\"\\d\", \"#\", ...)", "Replaces every digit."], ["(?P<year>...)", "Named groups can be read by name."], ["<.+?> versus <.+>", "Lazy takes the shortest match; greedy takes the longest."], ["re.I", "Case-insensitive flag."]],
  dryRun: { intro: "Why <code>&lt;.+&gt;</code> matches the whole <code>&lt;a&gt;&lt;b&gt;</code>:", headers: ["Part", "What it does"], rows: [["<", "matches the first <"], [".+", "greedy: grabs as much as possible, to the end of the text"], [">", "backs up to the last > it can find"], ["result", "&lt;a&gt;&lt;b&gt;, one big match; with +? it stops at the first &gt;"]] },
  realExample: { intro: "Count the severity levels in log lines with a compiled pattern.", code: `import re\nfrom collections import Counter\nlog = ["2026-11-02 ERROR disk full", "2026-11-02 INFO started", "2026-11-03 ERROR timeout", "bad line"]\npattern = re.compile(r"^(\\d{4}-\\d{2}-\\d{2}) (\\w+) ")\nlevels = Counter(m.group(2) for line in log if (m := pattern.match(line)))\nprint(dict(levels))`, out: `{'ERROR': 2, 'INFO': 1}` },
  mistakes: ["Forgetting the raw string so backslashes are eaten.", "Using <code>match</code> when you need <code>search</code>.", "Using <code>search</code> to validate a whole string (use <code>fullmatch</code>).", "Not escaping special characters (<code>\\.</code> for a literal dot).", "Using regular expressions on HTML."],
  practices: ["Test patterns on small examples first.", "Use <code>re.VERBOSE</code> to document long patterns.", "Compile patterns used many times.", "Prefer string methods (<code>startswith</code>, <code>split</code>) when they are enough."],
  interview: ["Difference between match, search and fullmatch?", "Greedy vs lazy?", "What is a capture group?", "Why shouldn't you parse HTML with regex?"],
  practiceQs: ["Write a pattern for a 6-digit PIN code.", "Extract all hashtags from a tweet.", "Why is a dot in a pattern dangerous without escaping?", "Replace multiple spaces by one."],
  revision: ["Raw strings; \\d \\w \\s; [ ]; * + ? { }.", "search, match, fullmatch, findall, sub, split.", "Groups (), named (?P<n>).", "Greedy vs lazy."],
  hinglish: "Regular expression text ka pattern likhne ki chhoti bhasha hai. Hamesha raw string r\"...\" use karo. validation ke liye fullmatch, kahin bhi dhoondhne ke liye search aur saare matches ke liye findall.",
  quiz: [
    mcq("Which function checks that the WHOLE string fits the pattern?", ["search", "match", "fullmatch", "findall"], 2, "fullmatch requires the entire string to match."),
    mcq("What does \\d+ match?", ["One digit", "One or more digits", "Any character", "A dollar sign"], 1, "+ means one or more."),
    mcq("What does re.findall(r\"a.\", \"abac\") return?", ["['ab', 'ac']", "['a', 'a']", "['abac']", "[]"], 0, "Each a followed by any character.", "OUTPUT_PREDICTION"),
    mcq("What does the lazy quantifier +? do?", ["Matches as much as possible", "Matches as little as possible", "Makes it optional", "Matches nothing"], 1, "It stops at the first possible end."),
    mcq("Why should regex patterns be raw strings?", ["Speed", "So backslashes reach the regex engine unchanged", "Required by re", "To allow Unicode"], 1, "Otherwise \\d would be interpreted by Python first.")
  ],
  tasks: [task("Sum the numbers in a text", "Read a line of text and print the sum of all the whole numbers (sequences of digits) that appear in it. Use re.findall.", "import re\ntext = input()\n# print the sum of all numbers in text\n", `import re\ntext = input()\nprint(sum(int(n) for n in re.findall(r"\\d+", text)))`, [["abc 12 x 7 and 100", "119"], ["no numbers", "0"]], [["abc 12 x 7 and 100", "119"], ["no numbers", "0"], ["a1b2c3", "6"], ["007 and 10", "17"], ["Rs 1200", "1200"]])],
});

